example:
// shop.bynk
context shop

type Box = { weight: Int }

service weigh {
    on call(b: Box) -> Effect[Int] by Caller { … }
}

// depot.bynk
context depot

consumes shop

type Box = { label: String }

shop.weigh(Box { label: "a" })        // ✗ a `depot` `Box` is not shaped like `shop`'s

type Box = { weight: Int }

shop.weigh(Box { weight: 3 })         // ✓ the same shape on both sides
